const payText = (input, settings) => `${input.kind === "nudge" ? "NIVO nhắc nhẹ: chưa thấy khoản chuyển cho đơn của bạn.\n" : "Cảm ơn bạn đã đồng ý! Bạn chuyển khoản theo thông tin sau:\n"}` +
    `Ngân hàng: ${settings.bankName}\nSố tài khoản: ${settings.accountNumber}\nChủ tài khoản: ${settings.accountName}\n` +
    `Số tiền: ${money(input.amount)}\nNội dung chuyển khoản (giữ đúng để hệ thống tự nhận tiền): ${input.payCode}`;

/**
 * `nivo-gtm.send-pay` (Gửi thông tin chuyển khoản): ONE act, `contact_message.send` with the amount, the account and the pay code the customer writes in the transfer memo (the `sepay.payment.paid` trigger
 * reads that code). It leaves the company, so a person approves it (locked ask, G1). Used for the first request and for the one reminder.
 */
class SendPay {
    run(input, reach) {
        const { error } = reach.call("contact_message.send", { provider: input.channel, to: input.to, text: payText(input, reach.settings) });
        if (error)
            return { sent: false, refusal: error.code };
        return { sent: true, refusal: "" };
    }
}

SendPay;

const quoteText = (input, settings) => `${input.leadName === "" ? "Chào bạn" : `Chào ${input.leadName}`}, ${settings.greeting}\n\nBáo giá ${input.code}\n${input.lines}\n${input.trialDays > 0 ? `Bạn được dùng thử ${String(input.trialDays)} ngày trước khi trả tiền.\n` : ""}\n${settings.closing}`;

/**
 * `nivo-gtm.send-quote` (Gửi báo giá): ONE act, `contact_message.send` of the quote to the lead on the channel they came from. The figures are the ones the `price` cell computed from the price-list
 * settings; nothing here changes a number. It leaves the company, so the engine holds it for a person's approval (locked ask, G1). A refusal of the channel is answered as `sent: false`.
 */
class SendQuote {
    run(input, reach) {
        const { error } = reach.call("contact_message.send", { provider: input.channel, to: input.to, text: quoteText(input, reach.settings) });
        if (error)
            return { sent: false, refusal: error.code };
        return { sent: true, refusal: "" };
    }
}

SendQuote;

const welcomeText = (input, settings) => `${input.leadName === "" ? "Chào bạn" : `Chào ${input.leadName}`}! Chào mừng bạn đến với NIVO, gói ${input.plan === "" ? "Vận hành" : input.plan}.\n${settings.welcome}`;

/** `nivo-gtm.send-welcome` (Gửi lời chào mừng): ONE act, `contact_message.send` of the welcome after activation. It leaves the company, so a person approves it (locked ask, G1). */
class SendWelcome {
    run(input, reach) {
        const { error } = reach.call("contact_message.send", { provider: input.channel, to: input.to, text: welcomeText(input, reach.settings) });
        if (error)
            return { sent: false, refusal: error.code };
        return { sent: true, refusal: "" };
    }
}

SendWelcome;

// Small pure helpers the cells inline (the compiler copies each helper a cell references into its stored text). No package import here: a stored cell imports nothing.
/** An ISO instant `hours` after `at` (an ISO instant). */
const plusHours = (at, hours) => new Date(Date.parse(at) + hours * 3600000).toISOString();

/**
 * `nivo-gtm.set-plan` (Điền gói cho đơn): the sales person answered "Báo giá" on the brief card, so the deal gets its plan (the default plan and months of the settings). One act, `object.update`: writing
 * the plan is what starts the quote workflow (the `plan` field changed on a deal in `proposal`).
 */
class SetPlan {
    run(input, reach) {
        const deal = reach.objects("gtm.deal").get(input.dealId);
        if (deal.error)
            throw deal.error;
        const { result, error } = reach.objects("gtm.deal").update({
            id: input.dealId,
            version: deal.result.version,
            values: { plan: reach.settings.defaultPlan, months: reach.settings.defaultMonths, nextAction: "Soát báo giá rồi duyệt gửi", nextAt: plusHours(reach.facts.at, reach.settings.quoteReviewHours) },
        });
        if (error)
            throw error;
        return { version: result.version, plan: reach.settings.defaultPlan, months: reach.settings.defaultMonths };
    }
}

SetPlan;

